<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\ThemeTenantVO;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\ThemeNameVO;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\ThemeIsDefaultVO;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\ThemeEnabledVO;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\ThemeCustomCssVO;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\ThemeVersionVO;
use Civi\Lughauth\Features\Document\Theme\Application\Usecase\Enable\ThemeEnableResult;
use PHPUnit\Framework\TestCase;

final class ThemeEnableResultUnitTest extends TestCase
{
    public function test(): void
    {
        $value = new ThemeEnableResult();
        $tenantOneValue = new TenantRef('one');
        $tenantOtherValue = new TenantRef('other');
        $copy = $value->tenant($tenantOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new TenantRef('one'), $value->getTenant());
        $this->assertNotEquals(new TenantRef('other'), $value->getTenant());
        $this->assertEquals(new TenantRef('one'), $value->getTenantOrCurrent(ThemeTenantVO::from($tenantOtherValue))->value());
        $this->assertNotEquals(new TenantRef('other'), $value->getTenantOrCurrent(ThemeTenantVO::from($tenantOtherValue))->value());
        $value->unsetTenant();
        $this->assertEquals(new TenantRef('other'), $value->getTenantOrCurrent(ThemeTenantVO::from($tenantOtherValue))->value());
        $this->assertNotEquals(new TenantRef('one'), $value->getTenantOrCurrent(ThemeTenantVO::from($tenantOtherValue))->value());
        $nameOneValue = 'one';
        $nameOtherValue = 'other';
        $copy = $value->name($nameOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getName());
        $this->assertNotEquals('other', $value->getName());
        $this->assertEquals('one', $value->getNameOrCurrent(ThemeNameVO::from($nameOtherValue))->value());
        $this->assertNotEquals('other', $value->getNameOrCurrent(ThemeNameVO::from($nameOtherValue))->value());
        $value->unsetName();
        $this->assertEquals('other', $value->getNameOrCurrent(ThemeNameVO::from($nameOtherValue))->value());
        $this->assertNotEquals('one', $value->getNameOrCurrent(ThemeNameVO::from($nameOtherValue))->value());
        $isDefaultOneValue = true;
        $isDefaultOtherValue = false;
        $copy = $value->isDefault($isDefaultOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(true, $value->isIsDefault());
        $this->assertNotEquals(false, $value->isIsDefault());
        $this->assertEquals(true, $value->getIsDefaultOrCurrent(ThemeIsDefaultVO::from($isDefaultOtherValue))->value());
        $this->assertNotEquals(false, $value->getIsDefaultOrCurrent(ThemeIsDefaultVO::from($isDefaultOtherValue))->value());
        $value->unsetIsDefault();
        $this->assertEquals(false, $value->getIsDefaultOrCurrent(ThemeIsDefaultVO::from($isDefaultOtherValue))->value());
        $this->assertNotEquals(true, $value->getIsDefaultOrCurrent(ThemeIsDefaultVO::from($isDefaultOtherValue))->value());
        $enabledOneValue = true;
        $enabledOtherValue = false;
        $copy = $value->enabled($enabledOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(true, $value->isEnabled());
        $this->assertNotEquals(false, $value->isEnabled());
        $this->assertEquals(true, $value->getEnabledOrCurrent(ThemeEnabledVO::from($enabledOtherValue))->value());
        $this->assertNotEquals(false, $value->getEnabledOrCurrent(ThemeEnabledVO::from($enabledOtherValue))->value());
        $value->unsetEnabled();
        $this->assertEquals(false, $value->getEnabledOrCurrent(ThemeEnabledVO::from($enabledOtherValue))->value());
        $this->assertNotEquals(true, $value->getEnabledOrCurrent(ThemeEnabledVO::from($enabledOtherValue))->value());
        $customCssOneValue = 'one';
        $customCssOtherValue = 'other';
        $copy = $value->customCss($customCssOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getCustomCss());
        $this->assertNotEquals('other', $value->getCustomCss());
        $this->assertEquals('one', $value->getCustomCssOrCurrent(ThemeCustomCssVO::from($customCssOtherValue))->value());
        $this->assertNotEquals('other', $value->getCustomCssOrCurrent(ThemeCustomCssVO::from($customCssOtherValue))->value());
        $value->unsetCustomCss();
        $this->assertEquals('other', $value->getCustomCssOrCurrent(ThemeCustomCssVO::from($customCssOtherValue))->value());
        $this->assertNotEquals('one', $value->getCustomCssOrCurrent(ThemeCustomCssVO::from($customCssOtherValue))->value());
        $versionOneValue = 1;
        $versionOtherValue = 2;
        $copy = $value->version($versionOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(1, $value->getVersion());
        $this->assertNotEquals(2, $value->getVersion());
        $this->assertEquals(1, $value->getVersionOrCurrent(ThemeVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(2, $value->getVersionOrCurrent(ThemeVersionVO::from($versionOtherValue))->value());
        $value->unsetVersion();
        $this->assertEquals(2, $value->getVersionOrCurrent(ThemeVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(1, $value->getVersionOrCurrent(ThemeVersionVO::from($versionOtherValue))->value());
        $this->assertSame($value, $copy);
    }
}
